SELECT current_database() AS database_name,to_regclass('public.hq_review_sms_preferences') IS NOT NULL AS prerequisite_094_present,EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='hq_review_sms_preferences' AND column_name='purchase') AS migration_already_present,(SELECT count(*) FROM public.hq_review_sms_preferences) AS preferences,(SELECT count(*) FROM public.hq_review_sms_preferences WHERE enabled) AS legacy_enabled;
